-- Course catalog instructors (Bilibili knowledge creators).
-- Generated by scripts/catalog/generate-course-seed-sql.mjs from
-- database/seeds/catalog/categories/<slug>.json. Do not edit by hand.
-- Tenant 100001 / org 0. Idempotent upserts keyed by deterministic ids.

ON CONFLICT (id) DO UPDATE SET
    display_name = EXCLUDED.display_name,
    title = EXCLUDED.title,
    bio = EXCLUDED.bio,
    avatar_resource_snapshot = EXCLUDED.avatar_resource_snapshot,
    expertise_tags_json = EXCLUDED.expertise_tags_json,
    qualification_status = EXCLUDED.qualification_status,
    sort_order = EXCLUDED.sort_order,
    status = EXCLUDED.status,
    updated_at = EXCLUDED.updated_at;
